css:
.cashchain-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e7e3d8;
    background: radial-gradient(1200px 600px at 50% -10%, #1f1a13 0%, #14110c 55%, #0d0b08 100%);
    border-radius: 18px;
}

.cashchain-container * {
    box-sizing: border-box;
}

.cashchain-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1a140a 0%, #2b2110 55%, #3a2c12 100%);
    color: #f4efe2;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #5a4416;
    box-shadow: 0 12px 34px rgba(0, 0, 0, 0.55);
}

.cashchain-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: 0.5px;
    color: #e9c66b;
    text-shadow: 0 2px 10px rgba(0, 0, 0, 0.4);
}

.cashchain-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 700;
    color: #d8b65a;
    background: rgba(233, 198, 107, 0.10);
    border: 1px solid rgba(233, 198, 107, 0.30);
    padding: 5px 14px;
    border-radius: 999px;
}

.cashchain-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cfc7b3;
}

.cashchain-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #c9bd9c;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.cashchain-period-counter #currentDay,
.cashchain-period-counter #maxPeriods {
    font-weight: 800;
    color: #e9c66b;
}

.cashchain-round-name {
    background: rgba(233, 198, 107, 0.14);
    color: #e9c66b;
    border: 1px solid rgba(233, 198, 107, 0.30);
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.cashchain-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ff9d7a;
    background: rgba(176, 58, 30, 0.20);
    border: 1px solid rgba(214, 92, 58, 0.40);
    padding: 4px 12px;
    border-radius: 999px;
}

.cashchain-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.cashchain-status-card {
    background: linear-gradient(160deg, #1c1810 0%, #16130c 100%);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #322914;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.45);
    border-top: 4px solid #6c5520;
}

.cashchain-card-cash { border-top-color: #3fb37a; }
.cashchain-card-resilience { border-top-color: #4f9fd6; }
.cashchain-card-sustain { border-top-color: #7bb83f; }
.cashchain-card-dpo { border-top-color: #d8b65a; }

.cashchain-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    font-weight: 700;
    color: #9d916f;
}

.cashchain-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #f4efe2;
    font-variant-numeric: tabular-nums;
}

.cashchain-card-cash .cashchain-value { color: #5fd39a; }
.cashchain-card-resilience .cashchain-value { color: #74bbe9; }
.cashchain-card-sustain .cashchain-value { color: #9fd35f; }
.cashchain-card-dpo .cashchain-value { color: #e9c66b; }

.cashchain-sublabel {
    font-size: 0.76rem;
    color: #8d8264;
    line-height: 1.35;
}

.cashchain-cash-hit .cashchain-value { color: #5fd39a; }
.cashchain-cash-short .cashchain-value { color: #ff9d7a; }

.cashchain-dpo-danger { border-top-color: #c0392b; }
.cashchain-dpo-danger .cashchain-value { color: #ff7a5c; }

.cashchain-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: linear-gradient(90deg, #241b0c 0%, #2f2410 100%);
    color: #efe6cf;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border: 1px solid #4a3915;
}

.cashchain-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e9c66b;
}

.cashchain-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(160deg, #1b1710 0%, #15120b 100%);
    border-left: 5px solid #e9c66b;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.40);
}

.cashchain-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.cashchain-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #e9c66b;
    margin-bottom: 6px;
}

.cashchain-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #d3cbb6;
}

.cashchain-briefing-text strong { color: #5fd39a; }
.cashchain-briefing-text em { color: #ff9d7a; font-style: italic; }

.cashchain-controls {
    background: linear-gradient(160deg, #1a1610 0%, #14110b 100%);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #322914;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.40);
}

.cashchain-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #e9c66b;
    border-bottom: 1px solid #3a2f16;
    padding-bottom: 8px;
}

.cashchain-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #ddd3b8;
    margin: 14px 0 6px;
}

.cashchain-container select,
.cashchain-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #4a3c1c;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #211b11;
    color: #f1ead8;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.cashchain-container select:focus,
.cashchain-container input[type="number"]:focus {
    outline: none;
    border-color: #e9c66b;
    box-shadow: 0 0 0 3px rgba(233, 198, 107, 0.18);
}

.cashchain-container select option {
    background-color: #211b11;
    color: #f1ead8;
}

.cashchain-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #e9c66b;
}

.cashchain-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #c9bd9c;
    margin-top: 4px;
}

.cashchain-range-readout span:last-child {
    color: #e9c66b;
    font-weight: 800;
}

.cashchain-hint {
    font-size: 0.8rem;
    color: #8d8264;
    margin-top: 4px;
    line-height: 1.4;
}

.cashchain-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.cashchain-container .btn-primary {
    background: linear-gradient(135deg, #b3892f 0%, #e9c66b 100%);
    border: none;
    color: #1a140a;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(179, 137, 47, 0.35);
}

.cashchain-container .btn-primary:hover {
    filter: brightness(1.07);
}

.cashchain-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #4a3c1c;
    color: #c9bd9c;
    background: transparent;
}

.cashchain-coach {
    background: linear-gradient(160deg, #221a0c 0%, #181206 100%);
    color: #ece2c8;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid #5a4416;
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.50);
}

.cashchain-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #d8b65a;
    margin-bottom: 8px;
}

.cashchain-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.cashchain-coach-body strong { color: #5fd39a; }
.cashchain-coach-body em { color: #ff9d7a; font-style: italic; }

.cashchain-history,
.cashchain-chart {
    background: linear-gradient(160deg, #1a1610 0%, #14110b 100%);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #322914;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.40);
}

.cashchain-history h3,
.cashchain-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #e9c66b;
}

.cashchain-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #d3cbb6;
}

.cashchain-container table#usfHistoryTable th {
    background: #241c0e;
    color: #e9c66b;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 1px solid #3a2f16;
}

.cashchain-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #261f12;
}

.cashchain-container table#usfHistoryTable tr:nth-child(even) td {
    background: rgba(233, 198, 107, 0.04);
}

.cashchain-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .cashchain-container {
        padding: 14px;
    }
    .cashchain-header h1 {
        font-size: 1.7rem;
    }
    .cashchain-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .cashchain-value {
        font-size: 2rem;
    }
    .cashchain-clock {
        margin-left: 0;
    }
    .cashchain-period-counter {
        font-size: 0.88rem;
    }
    .cashchain-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .cashchain-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion-message card (appended; dark-on-light, self-contained) */
.cashchain-cm { background:#f7faf8; color:#12211b; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(0,0,0,0.18); }
.cashchain-cm-head { text-align:center; border-bottom:1px solid #dde7e1; padding-bottom:14px; margin-bottom:16px; }
.cashchain-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#5a6b62; font-weight:700; }
.cashchain-cm-scorewrap { margin:8px 0 2px; }
.cashchain-cm-score { font-size:52px; font-weight:800; color:#0b7a4b; line-height:1; }
.cashchain-cm-score-max { font-size:20px; color:#84948b; font-weight:600; }
.cashchain-cm-grade { font-size:19px; font-weight:700; color:#12211b; margin-top:4px; }
.cashchain-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.cashchain-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.cashchain-cm-met { background:#d6f2e2; color:#0b6b41; }
.cashchain-cm-fail { background:#fce0dc; color:#a4322a; }
.cashchain-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.cashchain-cm-metric { background:#eef4f0; border-radius:10px; padding:12px 16px; min-width:104px; text-align:center; }
.cashchain-cm-metric-val { font-size:22px; font-weight:800; color:#12211b; }
.cashchain-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#5a6b62; margin-top:3px; }
.cashchain-cm-insights { background:#eef4f0; border-radius:10px; padding:14px 18px; }
.cashchain-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#5a6b62; font-weight:700; margin-bottom:8px; }
.cashchain-cm-insights ul { margin:0; padding-left:18px; }
.cashchain-cm-insights li { font-size:14px; line-height:1.5; color:#2a3a32; margin-bottom:7px; }

