(function() {
    'use strict';

    class CashChainAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Cash in the Chain`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Maison Velluti S.p.A. / EUR).
            this.CASH_TARGET = 30;       // CFO: free EUR 30M of working capital
            this.FUND_CAP = 12;          // ESG / supplier-finance fund, EUR 12M ceiling
            this.DPO_BASE = 75;          // current days payable outstanding
            this.DPO_BLUNT = 120;        // CFO's destructive proposal
            this.CONTRACTS_AT_RISK = 190;// EUR 190M of luxury contracts
            this.SF_SHARE = 22;          // San Frediano = 22% of certified leather

            // Concept-correct anchors (the positive-sum play).
            this.TRUE_LEVER = `scf`;
            this.TRUE_INSTRUMENT = `reverse`;
            this.TRUE_RATE = `esglinked`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cashFreed: 0,
                    resilience: 22,
                    sustain: 18,
                    dpo: this.DPO_BASE,
                    fundUsed: 0,
                    sanFredianoLost: false,
                    cashGrab: false,
                    targetMissed: false,
                    cashHistory: [0],
                    resilienceHistory: [22],
                    sustainHistory: [18],
                    dpoHistory: [this.DPO_BASE],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seed a MIDDLING / neutral mix — never the textbook-correct play.
                state.decisions = {
                    lever: `negotiate`,
                    segment: `spend`,
                    diagnosis: 50,
                    instrument: `dynamic`,
                    dpoTarget: 90,
                    rate: `tiered`,
                    fund: 4,
                    sanFrediano: `qualify`,
                    onboard: `standard`,
                    compliance: `mixed`,
                    develop: 40,
                    stress: `cashfirst`,
                    board: `cfoonly`,
                    governance: `treasury`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const lever = document.getElementById(`leverInput`);
                const segment = document.getElementById(`segmentInput`);
                const diag = document.getElementById(`diagnosisInput`);
                if (lever) decisions.lever = lever.value;
                if (segment) decisions.segment = segment.value;
                if (diag) decisions.diagnosis = parseInt(diag.value, 10);
                if (!Number.isFinite(decisions.diagnosis) || decisions.diagnosis < 0 || decisions.diagnosis > 100) {
                    warn(`warn_diagnosis_range`); return false;
                }
            } else if (round === 2) {
                const inst = document.getElementById(`instrumentInput`);
                const dpoT = document.getElementById(`dpoTargetInput`);
                const rate = document.getElementById(`rateInput`);
                const fund = document.getElementById(`fundInput`);
                if (inst) decisions.instrument = inst.value;
                if (rate) decisions.rate = rate.value;
                if (dpoT) decisions.dpoTarget = parseInt(dpoT.value, 10);
                if (fund) decisions.fund = parseFloat(fund.value);
                if (!Number.isFinite(decisions.dpoTarget) || decisions.dpoTarget < this.DPO_BASE || decisions.dpoTarget > this.DPO_BLUNT) {
                    warn(`warn_dpo_range`); return false;
                }
                if (!Number.isFinite(decisions.fund) || decisions.fund < 0 || decisions.fund > this.FUND_CAP) {
                    warn(`warn_fund_range`); return false;
                }
            } else if (round === 3) {
                const sf = document.getElementById(`sanfredianoInput`);
                const onb = document.getElementById(`onboardInput`);
                const comp = document.getElementById(`complianceInput`);
                const dev = document.getElementById(`developInput`);
                if (sf) decisions.sanFrediano = sf.value;
                if (onb) decisions.onboard = onb.value;
                if (comp) decisions.compliance = comp.value;
                if (dev) decisions.develop = parseInt(dev.value, 10);
                if (!Number.isFinite(decisions.develop) || decisions.develop < 0 || decisions.develop > 100) {
                    warn(`warn_develop_range`); return false;
                }
            } else if (round === 4) {
                const str = document.getElementById(`stressInput`);
                const bo = document.getElementById(`boardInput`);
                const gov = document.getElementById(`governanceInput`);
                const cv = document.getElementById(`convictionInput`);
                if (str) decisions.stress = str.value;
                if (bo) decisions.board = bo.value;
                if (gov) decisions.governance = gov.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas this round.
            let cashDelta = 0, resilienceDelta = 0, sustainDelta = 0, spend = 0;
            let dpoSet = null;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the bind. Refuse the blunt cash grab; segment before acting.
                switch (d.lever) {
                    case `scf`:
                        cashDelta += 4; resilienceDelta += 10; sustainDelta += 2; coachKey = `coach_r1_scf`; break;
                    case `negotiate`:
                        cashDelta += 3; resilienceDelta += 3; coachKey = `coach_r1_negotiate`; break;
                    case `stretch`:
                        // The cheap, destructive lever: frees cash now, craters the chain.
                        cashDelta += 12; resilienceDelta -= 18; sustainDelta -= 6;
                        ds.cashGrab = true; coachKey = `coach_r1_stretch`; break;
                    case `inventory`:
                        cashDelta += 2; resilienceDelta -= 2; coachKey = `coach_r1_inventory`; break;
                }

                switch (d.segment) {
                    case `kraljic`:
                        resilienceDelta += 10; sustainDelta += 3;
                        if (d.lever === this.TRUE_LEVER) coachKey = `coach_r1_diag_sharp`; break;
                    case `spend`:
                        resilienceDelta -= 4; coachKey = (d.lever === `stretch`) ? coachKey : `coach_r1_spend`; break;
                    case `none`:
                        resilienceDelta -= 8; sustainDelta -= 2; coachKey = (d.lever === `stretch`) ? coachKey : `coach_r1_noseg`; break;
                }

                // Clarity of the trap (cheap cash lever = EUR 190M revenue risk).
                if (d.diagnosis >= 60) { resilienceDelta += 5; }
                else if (d.diagnosis <= 25) { resilienceDelta -= 5; coachKey = `coach_r1_blind`; }

                summaryKey = (d.lever === this.TRUE_LEVER && d.segment === `kraljic`) ? `sum_r1_good`
                    : (d.lever === `stretch` ? `sum_r1_grab` : `sum_r1_weak`);
            } else if (round === 2) {
                // Choose the instrument + set effective DPO + financing rate + ESG fund.
                // Cash freed scales with how far you push DPO, BUT the instrument decides
                // whether that is positive-sum (reverse factoring) or destructive.
                const dpoStretch = Math.max(0, d.dpoTarget - this.DPO_BASE); // 0..45 days
                dpoSet = d.dpoTarget;

                switch (d.instrument) {
                    case `reverse`:
                        // ~0.78 EUR M of cash per extra day, with diminishing returns past 105d.
                        // Suppliers paid early by the bank at the buyer's rating -> resilience holds/grows.
                        cashDelta += dpoStretch * 0.78 - Math.max(0, d.dpoTarget - 105) * 0.30;
                        resilienceDelta += 10;
                        if (d.dpoTarget > 110) resilienceDelta -= 4; // even reverse factoring strains SMEs if pushed to the wall
                        coachKey = `coach_r2_reverse`;
                        break;
                    case `dynamic`:
                        // Uses YOUR cash for early-payment discounts: helps margin, does NOT free cash.
                        cashDelta -= 5; resilienceDelta += 7; sustainDelta += 1;
                        coachKey = `coach_r2_dynamic`;
                        break;
                    case `factoring`:
                        // Supplier-led, costlier for them; frees some buyer cash via DPO but strains suppliers.
                        cashDelta += dpoStretch * 0.30; resilienceDelta -= 4;
                        coachKey = `coach_r2_factoring`;
                        break;
                    case `none`:
                        // Direct renegotiation = a quieter version of the stretch.
                        cashDelta += dpoStretch * 0.34; resilienceDelta -= dpoStretch * 0.18;
                        if (d.dpoTarget >= 115) ds.cashGrab = true;
                        coachKey = `coach_r2_none`;
                        break;
                }

                // Pushing DPO to the wall hurts the fragile tier regardless of instrument
                // (reverse factoring softens it, but does not erase it).
                if (d.dpoTarget >= 115 && d.instrument !== `reverse`) { resilienceDelta -= 8; ds.cashGrab = true; }
                else if (d.dpoTarget >= 115) { resilienceDelta -= 3; }

                // Financing rate design drives the sustainability cascade.
                switch (d.rate) {
                    case `esglinked`: sustainDelta += 14; resilienceDelta += 3; coachKey = (d.instrument === this.TRUE_INSTRUMENT) ? `coach_r2_anchor` : coachKey; break;
                    case `tiered`: sustainDelta += 3; coachKey = (coachKey === `coach_r2_reverse`) ? `coach_r2_tiered` : coachKey; break;
                    case `flat`: sustainDelta -= 4; resilienceDelta -= 2; break;
                }

                // ESG / supplier-finance fund committed (spend against the EUR 12M cap).
                spend += d.fund;
                if (d.fund >= 6) { sustainDelta += 6; resilienceDelta += 4; }
                else if (d.fund >= 3) { sustainDelta += 3; resilienceDelta += 2; }
                else { sustainDelta -= 3; resilienceDelta -= 2; }

                summaryKey = (d.instrument === this.TRUE_INSTRUMENT && d.rate === this.TRUE_RATE) ? `sum_r2_good`
                    : (d.instrument === `dynamic` ? `sum_r2_margin` : `sum_r2_weak`);
            } else if (round === 3) {
                // Rescue San Frediano, onboard the fragile tier, FINANCE compliance, develop the tier.
                switch (d.sanFrediano) {
                    case `rescue`:
                        resilienceDelta += 16; sustainDelta += 4; coachKey = `coach_r3_rescue`; break;
                    case `qualify`:
                        // Lose 22% certified leather, scramble to a sole source.
                        resilienceDelta -= 8; ds.sanFredianoLost = true; coachKey = `coach_r3_qualify`; break;
                    case `exit`:
                        // Single-source concentration on certified leather: worst resilience.
                        resilienceDelta -= 16; ds.sanFredianoLost = true; coachKey = `coach_r3_exit`; break;
                }

                switch (d.onboard) {
                    case `concierge`:
                        resilienceDelta += 12; sustainDelta += 6; coachKey = (d.sanFrediano === `rescue`) ? `coach_r3_reach` : coachKey; break;
                    case `standard`:
                        resilienceDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r3_standard` : coachKey; break;
                    case `exclude`:
                        // The SCF programme excludes the exact tier it should protect (Common Error 3).
                        resilienceDelta -= 12; sustainDelta -= 6; coachKey = `coach_r3_exclude`; break;
                }

                switch (d.compliance) {
                    case `finance`:
                        sustainDelta += 16; resilienceDelta += 4; spend += 3; break;
                    case `mixed`:
                        sustainDelta += 6; resilienceDelta -= 2; spend += 1.5; break;
                    case `mandate`:
                        // Demand compliance the artisanal base cannot fund (Common Error 4).
                        sustainDelta -= 10; resilienceDelta -= 10; coachKey = `coach_r3_mandate`; break;
                }

                // Steering the fund to the critical-but-fragile tier.
                if (d.develop >= 40 && d.develop <= 70) { resilienceDelta += 8; sustainDelta += 4; }
                else if (d.develop < 20) { resilienceDelta -= 8; coachKey = (coachKey === `coach_default`) ? `coach_r3_starve` : coachKey; }
                else if (d.develop > 85) { resilienceDelta += 2; sustainDelta -= 2; } // over-concentrating on one tier

                summaryKey = (d.sanFrediano === `rescue` && d.onboard === `concierge` && d.compliance === `finance`) ? `sum_r3_good`
                    : (d.sanFrediano === `exit` || d.onboard === `exclude` || d.compliance === `mandate` ? `sum_r3_break` : `sum_r3_weak`);
            } else if (round === 4) {
                // Integrate, stress-test, defend.
                switch (d.stress) {
                    case `integrated`:
                        cashDelta += 4; resilienceDelta += 8; sustainDelta += 8; coachKey = `coach_r4_integrated`; break;
                    case `cashfirst`:
                        // Push DPO harder for cash, accept supplier strain.
                        cashDelta += 7; resilienceDelta -= 10; sustainDelta -= 4;
                        ds.dpo = Math.min(this.DPO_BLUNT, ds.dpo + 12);
                        if (ds.dpo >= 115) ds.cashGrab = true;
                        coachKey = `coach_r4_cashfirst`; break;
                    case `suppliersfirst`:
                        // Protect everyone, fall short of the EUR 30M.
                        cashDelta -= 6; resilienceDelta += 6; sustainDelta += 3; coachKey = `coach_r4_suppliersfirst`; break;
                }

                switch (d.board) {
                    case `positivesum`:
                        resilienceDelta += 6; sustainDelta += 6; coachKey = (d.stress === `integrated`) ? `coach_r4_positivesum` : coachKey; break;
                    case `cfoonly`:
                        cashDelta += 2; resilienceDelta -= 4; sustainDelta -= 4; coachKey = `coach_r4_cfoonly`; break;
                    case `optimistic`:
                        resilienceDelta -= 8; sustainDelta -= 6; coachKey = `coach_r4_optimistic`; break;
                }

                switch (d.governance) {
                    case `owned`: resilienceDelta += 8; sustainDelta += 8; break;
                    case `treasury`: sustainDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_treasury` : coachKey; break;
                    case `none`: resilienceDelta -= 8; sustainDelta -= 8; coachKey = `coach_r4_none`; break;
                }

                // Conviction nudges resilience.
                resilienceDelta += Math.round((d.conviction - 60) / 10);

                summaryKey = (d.stress === `integrated` && d.board === `positivesum` && d.governance === `owned`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply effective DPO if set this round.
            if (dpoSet !== null) ds.dpo = dpoSet;

            // Resource accounting (ESG / supplier-finance fund, EUR M, capped at the ceiling).
            ds.fundUsed = Math.min(this.FUND_CAP, Math.round((ds.fundUsed + spend) * 10) / 10);

            // If San Frediano is lost, certified-leather resilience is permanently capped lower.
            ds.cashFreed = Math.max(0, Math.round((ds.cashFreed + cashDelta) * 10) / 10);
            ds.resilience = Math.max(0, Math.min(100, ds.resilience + resilienceDelta));
            ds.sustain = Math.max(0, Math.min(100, ds.sustain + sustainDelta));
            // A blunt cash grab (DPO stretched onto suppliers who can't fund it) leaves a permanent
            // scar on the chain: later good moves cannot fully launder away the strain it caused.
            // Without this ceiling the 0-100 resilience meter saturates at its clamp and hides the
            // single most important lesson — the destructive stretch ends up looking like a clean win.
            if (ds.cashGrab) ds.resilience = Math.min(ds.resilience, 72); // hard ceiling: destructive DPO stretch
            if (ds.sanFredianoLost) ds.resilience = Math.min(ds.resilience, 58); // hard ceiling: single-source certified leather

            ds.cashHistory.push(Math.round(ds.cashFreed * 10) / 10);
            ds.resilienceHistory.push(Math.round(ds.resilience));
            ds.sustainHistory.push(Math.round(ds.sustain));
            ds.dpoHistory.push(Math.round(ds.dpo));

            if (round === this.ROUNDS.length && ds.cashFreed < this.CASH_TARGET) ds.targetMissed = true;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            // v1.1.0 fix: persist instructor-card composite to domainState every period.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                cashFreed: Math.round(ds.cashFreed * 10) / 10,
                cashDelta: Math.round(cashDelta * 10) / 10,
                resilience: Math.round(ds.resilience),
                resilienceDelta: Math.round(resilienceDelta),
                sustain: Math.round(ds.sustain),
                sustainDelta: Math.round(sustainDelta),
                dpo: Math.round(ds.dpo),
                fundUsed: ds.fundUsed,
                sanFredianoLost: ds.sanFredianoLost,
                cashGrab: ds.cashGrab,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

