                const card = document.querySelector(`.cashchain-card-dpo`);
                if (card) card.classList.toggle(`cashchain-dpo-danger`, Number(v) >= 115);
                return Math.round(Number(v)) + `d`;
            });
            uiManager.bind(`budgetDisplay`, `domainState.fundUsed`, (v) => {
                const used = Math.round(Number(v) * 10) / 10;
                return lang() === `es`
