        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.cashHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : window.mySimulation.t(`chart_round_prefix`) + i));
            return {
                cashchainChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.cashHistory },
                        { data: ds.resilienceHistory },
                        { data: ds.sustainHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            const cash = Math.round(ds.cashFreed * 10) / 10;
            const resilience = Math.round(ds.resilience);
            const sustain = Math.round(ds.sustain);
            const cashScore = Math.min(100, (cash / this.CASH_TARGET) * 100);
            return Math.round(cashScore * 0.34 + resilience * 0.33 + sustain * 0.33);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const cash = Math.round(ds.cashFreed * 10) / 10;
            const resilience = Math.round(ds.resilience);
            const sustain = Math.round(ds.sustain);

            const hitCash = cash >= this.CASH_TARGET;
            const chainAlive = resilience >= 60 && !ds.sanFredianoLost;
            const codesPass = sustain >= 60;
            const grab = ds.cashGrab || (hitCash && resilience < 40);

            // Composite: cash (capped at target), resilience, sustainability — equally weighted.
            const composite = this._composite(ds);

            let performanceKey = `grade_strain`;
            if (hitCash && chainAlive && codesPass && composite >= 80 && !grab) performanceKey = `grade_positivesum`;
            else if (hitCash && chainAlive && codesPass && !grab) performanceKey = `grade_held`;
            else if (hitCash && grab) performanceKey = `grade_grab`;
            else if (hitCash) performanceKey = `grade_exposed`;
            else if (cash >= this.CASH_TARGET * 0.6) performanceKey = `grade_short`;
            const met = hitCash && chainAlive && codesPass && composite >= 80 && !grab;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (hitCash && chainAlive && codesPass) insights.push(window.mySimulation.t(`insight_positivesum`));
            else if (hitCash && grab) insights.push(window.mySimulation.t(`insight_grab`));
            else if (hitCash) insights.push(window.mySimulation.t(`insight_exposed`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.sanFredianoLost) insights.push(window.mySimulation.t(`insight_sanfrediano`));
            if (sustain < 45) insights.push(window.mySimulation.t(`insight_codes`));
            if (ds.dpo >= 115) insights.push(window.mySimulation.t(`insight_dpo`));
            if (hitCash && chainAlive && codesPass && sustain >= 70) insights.push(window.mySimulation.t(`insight_cascade`));

            return {
                cashFreed: cash,
                resilience: resilience,
                sustain: sustain,
                dpo: Math.round(ds.dpo),
                hitCash: hitCash,
                chainAlive: chainAlive,
                grab: grab,
                codesPass: codesPass,
                sanFredianoLost: !!ds.sanFredianoLost,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="cashchain-cm-badge ` + (s.met ? `cashchain-cm-met` : `cashchain-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.grab) badges.push(`<span class="cashchain-cm-badge cashchain-cm-fail">` + t(`cm_fail_grab`) + `</span>`);
            if (s.sanFredianoLost) badges.push(`<span class="cashchain-cm-badge cashchain-cm-fail">` + t(`cm_fail_sf`) + `</span>`);
            if (s.chainAlive === false) badges.push(`<span class="cashchain-cm-badge cashchain-cm-fail">` + t(`cm_fail_chain`) + `</span>`);
            const kpi = (label, val) => `<div class="cashchain-cm-metric"><div class="cashchain-cm-metric-val">` + val + `</div><div class="cashchain-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_cash`), (s.cashFreed != null ? s.cashFreed : 0)) + kpi(t(`cm_resilience`), (s.resilience != null ? s.resilience : 0)) + kpi(t(`cm_sustain`), (s.sustain != null ? s.sustain : 0)) + kpi(t(`cm_dpo`), (s.dpo != null ? s.dpo : 0));
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="cashchain-cm">`
                + `<div class="cashchain-cm-head"><div class="cashchain-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="cashchain-cm-scorewrap"><span class="cashchain-cm-score">` + score + `</span><span class="cashchain-cm-score-max">/100</span></div>`
                + `<div class="cashchain-cm-grade">` + grade + `</div>`
                + `<div class="cashchain-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="cashchain-cm-metrics">` + kpis + `</div>`
                + `<div class="cashchain-cm-insights"><div class="cashchain-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.cashGrab) return window.mySimulation.t(`hint_grab`);
            if (ds.sanFredianoLost && state.currentPeriod >= 3) return window.mySimulation.t(`hint_sanfrediano`);
            if (ds.resilience < 35) return window.mySimulation.t(`hint_resilience`);
            if (ds.sustain < 35) return window.mySimulation.t(`hint_sustain`);
            if (state.currentPeriod >= 3 && ds.cashFreed < 14) return window.mySimulation.t(`hint_cash`);
            if (ds.cashFreed >= this.CASH_TARGET && ds.resilience >= 60 && ds.sustain >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

